import json,sys
d=json.load(open('macos.json'))
def walk(o,out):
    if isinstance(o,dict):
        if o.get('type')=='text': out.append(o.get('text',''))
        elif o.get('type')=='codeVoice': out.append('\`'+o.get('code','')+'\`')
        elif o.get('type')=='heading': out.append('\n\n## '+o.get('text','')+'\n')
        elif o.get('type')=='paragraph':
            sub=[];[walk(c,sub) for c in o.get('inlineContent',[])];out.append('\n'+''.join(sub)+'\n')
        elif o.get('type') in ('unorderedList','orderedList'):
            for it in o.get('items',[]):
                sub=[];walk(it,sub);out.append('\n- '+''.join(sub).strip())
        else:
            for v in o.values(): walk(v,out)
    elif isinstance(o,list):
        for v in o: walk(v,out)
out=[]
walk(d.get('primaryContentSections',[]),out)
walk(d.get('abstract',[]),out)
print(''.join(out))
